{currentTrack && (
  <div className="flex flex-wrap items-center justify-center gap-2 font-mono text-xs text-[#8c7a9e] pt-1">
    {/* Origin Playlist/Channel Name with Add to Custom Playlist Popover */}
    <div className="relative inline-flex items-center" ref={addToPlaylistRef}>
      <span className="text-[#ffd86b] font-semibold">{currentTrack.channel}</span>
      <button
        type="button"
        onClick={() => setIsAddToPlaylistOpen((prev) => !prev)}
        className={`ml-1.5 inline-flex items-center gap-1 px-2 py-0.5 rounded-full border text-[11px] font-mono font-medium transition-all cursor-pointer ${
          isAddToPlaylistOpen
            ? 'bg-[#2b1f3d] border-[#ffd86b] text-[#ffd86b] shadow-[0_0_10px_rgba(255,216,107,0.3)]'
            : 'bg-[#1a1424] hover:bg-[#261c33] border-[#3d304f] hover:border-[#d4af37]/70 text-[#cbd5e1] hover:text-[#ffd86b]'
        }`}
        title={`Add origin playlist "${currentTrack.channel}" to a custom playlist`}
      >
        <Plus className="w-3 h-3 text-[#ffd86b]" />
        <span>Playlist</span>
        <ChevronDown
          className={`w-2.5 h-2.5 text-[#8c7a9e] transition-transform duration-200 ${
            isAddToPlaylistOpen ? 'rotate-180' : ''
          }`}
        />
      </button>

      {/* Add to Custom Playlist Popover Dropdown */}
      {isAddToPlaylistOpen && (
        <div className="absolute left-1/2 -translate-x-1/2 top-full mt-2 w-80 max-w-[90vw] bg-[#140f1c] border border-[#d4af37]/70 rounded-2xl shadow-2xl z-50 overflow-hidden flex flex-col text-left animate-in fade-in zoom-in-95 duration-150 font-sans">
          {/* Popover Header */}
          <div className="p-3 border-b border-[#2b2238] bg-[#1a1424] flex items-center justify-between">
            <div className="flex items-center gap-2">
              <ListMusic className="w-4 h-4 text-[#ffd86b]" />
              <span className="font-cinzel text-xs font-bold text-[#f5f0e8]">
                Add to Custom Playlist
              </span>
            </div>
            <button
              type="button"
              onClick={() => setIsAddToPlaylistOpen(false)}
              className="p-1 text-[#8c7a9e] hover:text-white rounded-lg hover:bg-[#261d33] transition cursor-pointer"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>

          {/* Origin Channel Display */}
          <div className="px-3 py-2 bg-[#0d0914] border-b border-[#231b2e] flex items-center justify-between text-xs">
            <span className="text-[#8c7a9e] text-[11px] font-mono">Origin Playlist:</span>
            <span className="font-semibold text-[#ffd86b] truncate max-w-[170px]" title={currentTrack.channel}>
              {currentTrack.channel}
            </span>
          </div>

          {/* Search Input (if > 3 playlists exist) */}
          {customPlaylists.length > 3 && (
            <div className="p-2 border-b border-[#231b2e] bg-[#120d1a]">
              <div className="relative">
                <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-[#8c7a9e]" />
                <input
                  type="text"
                  value={playlistSearchQuery}
                  onChange={(e) => setPlaylistSearchQuery(e.target.value)}
                  placeholder="Search custom playlists..."
                  className="w-full pl-8 pr-2 py-1 text-xs bg-[#1a1424] border border-[#2b2238] rounded-lg text-white placeholder-[#8c7a9e] focus:outline-none focus:border-[#ffd86b]"
                />
              </div>
            </div>
          )}

          {/* Playlist List */}
          <div className="max-h-56 overflow-y-auto divide-y divide-[#231b2e] p-1">
            {filteredCustomPlaylists.length === 0 ? (
              <div className="p-4 text-center text-xs text-[#8c7a9e] space-y-1">
                <ListMusic className="w-6 h-6 mx-auto text-[#3d304f]" />
                <p className="font-medium text-[#cbd5e1]">
                  {customPlaylists.length === 0 ? 'No custom playlists yet' : 'No matching playlists'}
                </p>
                <p className="text-[11px]">
                  {customPlaylists.length === 0 ? 'Create your first one below.' : 'Try a different search query.'}
                </p>
              </div>
            ) : (
              filteredCustomPlaylists.map((pl) => {
                const isAlreadyMember = pl.channels.includes(currentTrack.channel.trim());
                const isSaving = savingPlaylistId === pl.id;

                return (
                  <div
                    key={pl.id}
                    className="p-2 flex items-center justify-between gap-2 hover:bg-[#1a1424] rounded-lg transition"
                  >
                    <div className="flex items-center gap-2 min-w-0 flex-1">
                      <span className="text-base flex-shrink-0">{pl.emoji || '🎵'}</span>
                      <div className="min-w-0 flex-1">
                        <p className="text-xs font-semibold text-[#f5f0e8] truncate" title={pl.name}>
                          {pl.name}
                        </p>
                        <p className="text-[10px] text-[#8c7a9e] font-mono">
                          {pl.channels.length} {pl.channels.length === 1 ? 'channel' : 'channels'}
                        </p>
                      </div>
                    </div>

                    {isAlreadyMember ? (
                      <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-mono font-bold bg-emerald-950/70 border border-emerald-500/50 text-emerald-400">
                        <Check className="w-3 h-3 text-emerald-400" />
                        <span>In Playlist</span>
                      </span>
                    ) : (
                      <button
                        type="button"
                        disabled={isSaving}
                        onClick={() => handleAddChannelToPlaylist(pl)}
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-[11px] font-mono font-bold bg-[#261c33] hover:bg-[#342447] text-[#ffd86b] border border-[#3d304f] hover:border-[#ffd86b] transition cursor-pointer disabled:opacity-50"
                      >
                        {isSaving ? (
                          <RefreshCw className="w-3 h-3 animate-spin text-[#ffd86b]" />
                        ) : (
                          <Plus className="w-3 h-3 text-[#ffd86b]" />
                        )}
                        <span>Add</span>
                      </button>
                    )}
                  </div>
                );
              })
            )}
          </div>

          {/* Quick Create New Playlist */}
          <form
            onSubmit={handleQuickCreatePlaylist}
            className="p-2.5 border-t border-[#231b2e] bg-[#120d1a] flex items-center gap-1.5"
          >
            <input
              type="text"
              value={quickPlaylistName}
              onChange={(e) => setQuickPlaylistName(e.target.value)}
              placeholder="New playlist name..."
              className="flex-1 px-2.5 py-1 text-xs bg-[#1a1424] border border-[#2b2238] rounded-lg text-white placeholder-[#8c7a9e] focus:outline-none focus:border-[#ffd86b]"
            />
            <button
              type="submit"
              disabled={isQuickCreating || !quickPlaylistName.trim()}
              className="px-2.5 py-1 bg-[#ffd86b] hover:bg-[#ffe394] text-black font-semibold text-xs rounded-lg transition flex items-center gap-1 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {isQuickCreating ? (
                <RefreshCw className="w-3 h-3 animate-spin" />
              ) : (
                <Plus className="w-3 h-3" />
              )}
              <span>Create</span>
            </button>
          </form>

          {/* Open Full Playlist Manager Footer */}
          <div className="p-2 border-t border-[#231b2e] bg-[#0d0914] text-center">
            <button
              type="button"
              onClick={() => {
                setIsAddToPlaylistOpen(false);
                setPreselectedChannelForModal(currentTrack.channel);
                setIsPlaylistModalOpen(true);
              }}
              className="text-[11px] font-mono text-[#ffd86b] hover:underline flex items-center justify-center gap-1 w-full py-0.5 cursor-pointer"
            >
              <span>Open in Full Playlist Manager...</span>
            </button>
          </div>
        </div>
      )}
    </div>

