// path: src/apps/vinyl-angel/VinylAngel.tsx

import { useState } from 'react';
import { useVinylStore } from './store/useVinylStore';
import { VinylPlayer } from './components/VinylPlayer';
import { VinylGallery } from './components/VinylGallery';
import { VinylPlaylists } from './components/VinylPlaylists';
import { VinylIngestion } from './components/VinylIngestion';
import { VinylConfig } from './components/VinylConfig';
import { GameLayout } from '../../components/GameLayout';
import {
  Disc3,
  Trophy,
  ListMusic,
  DownloadCloud,
  Sliders,
} from 'lucide-react';

const TARGET_PROJECT_ID = 'music_app';

type VinylTab = 'gameplay' | 'gallery' | 'playlists' | 'ingestion' | 'config';

export function VinylAngel() {
  const { localTheme, discs, angelRollTickets } = useVinylStore();

  const [activeTab, setActiveTab] = useState<VinylTab>('gameplay');

  // Theme styling mapping for wrapper
  const themeClasses: Record<string, string> = {
    'celestial-gold': 'bg-[#0c0b0e] text-[#f5f0e8]',
    'obsidian-abyss': 'bg-[#050505] text-[#e2e8f0]',
    'crimson-void': 'bg-[#0d0406] text-[#fde8e8]',
    'emerald-sanctuary': 'bg-[#040d08] text-[#ecfdf5]',
    'cyber-neon': 'bg-[#070512] text-[#fdf4ff]',
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 p-4 md:p-8 font-sans ${themeClasses[localTheme] || themeClasses['celestial-gold']}`}>
      <GameLayout
        showBackButton={true}
        backButtonLabel="Golden Hour"
        title="Vinyl Angel"
        gameTitleIcon={<Disc3 className="w-5 h-5 text-[#ffd86b]" />}
        gameTitleBadge="天界黑胶"
        gameTitleSubtitle="Autonomous Music Laboratory, Harmonic Hazard Scoring & Dynamic ETL Ingestion"
        globalInfo={{
          hazardLevel: undefined,
          goldenHours: undefined,
          discs: discs,
          tickets: angelRollTickets
        }}
        tabs={[
          { id: 'gameplay', label: 'Gameplay', icon: <Disc3 className="w-4 h-4" /> },
          { id: 'gallery', label: 'Gallery & Sync', icon: <Trophy className="w-4 h-4" /> },
          { id: 'playlists', label: 'Playlists', icon: <ListMusic className="w-4 h-4" /> },
          { id: 'ingestion', label: 'Song Ingestion', icon: <DownloadCloud className="w-4 h-4" /> },
          { id: 'config', label: 'Config', icon: <Sliders className="w-4 h-4" /> },
        ]}
        activeTab={activeTab}
        onTabChange={(id) => setActiveTab(id as VinylTab)}
      >
        <div className={activeTab === 'gameplay' ? 'block' : 'hidden'}>
          <VinylPlayer
            projectId={TARGET_PROJECT_ID}
            onNavigateToIngestion={() => setActiveTab('ingestion')}
          />
        </div>

        <div className={activeTab === 'gallery' ? 'block' : 'hidden'}>
          <VinylGallery
            projectId={TARGET_PROJECT_ID}
            onNavigateToIngestion={() => setActiveTab('ingestion')}
            onNavigateToGameplay={() => setActiveTab('gameplay')}
          />
        </div>

        <div className={activeTab === 'playlists' ? 'block' : 'hidden'}>
          <VinylPlaylists
            projectId={TARGET_PROJECT_ID}
            onNavigateToGameplay={() => setActiveTab('gameplay')}
          />
        </div>

        <div className={activeTab === 'ingestion' ? 'block' : 'hidden'}>
          <VinylIngestion
            projectId={TARGET_PROJECT_ID}
            onNavigateToGameplay={() => setActiveTab('gameplay')}
            onNavigateToGallery={() => setActiveTab('gallery')}
          />
        </div>

        <div className={activeTab === 'config' ? 'block' : 'hidden'}>
          <VinylConfig />
        </div>
      </GameLayout>
    </div>
  );
}

export default VinylAngel;

// path: src/App.tsx

import { useEffect, useRef } from 'react'
import { ThemeProvider } from './themes/ThemeProvider'
import { AppManager } from './core/AppManager'
import { useGlobalStore } from './store/useGlobalStore'

export default function App() {
  const loadFromBackend = useGlobalStore((s) => s.loadFromBackend)
  const isOnline = useGlobalStore((s) => s.isOnline)

  // Track previous online state so we can detect offline → online recovery
  const wasOnlineRef = useRef<boolean>(true)

  // ── 1. Initial hydration on cold mount ────────────────────────────────────
  useEffect(() => {
    loadFromBackend()
  }, [loadFromBackend])

  // ── 2. Periodic background re-hydration every 60 seconds ─────────────────
  // Keeps currency, inventory and vault in sync without requiring F5.
  useEffect(() => {
    const timer = setInterval(() => {
      loadFromBackend()
    }, 60_000)
    return () => clearInterval(timer)
  }, [loadFromBackend])

  // ── 3. Tab-focus re-hydration via Page Visibility API ─────────────────────
  // Re-syncs the moment the user switches back to this tab.
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        loadFromBackend()
      }
    }
    document.addEventListener('visibilitychange', handleVisibilityChange)
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange)
  }, [loadFromBackend])

  // ── 4. Online-recovery re-hydration ───────────────────────────────────────
  // When the backend flips from offline → online, immediately re-hydrate
  // to pick up any mutations that happened while we were disconnected.
  useEffect(() => {
    const wasOffline = !wasOnlineRef.current
    if (wasOffline && isOnline) {
      loadFromBackend()
    }
    wasOnlineRef.current = isOnline
  }, [isOnline, loadFromBackend])

  return (
    <ThemeProvider>
      <AppManager />
    </ThemeProvider>
  )
}

import json
import shutil
import sqlite3
from pathlib import Path
from datetime import datetime
from typing import Optional, Any, Dict, List
from fastapi import HTTPException
from pydantic import BaseModel

BACKEND_DIR = Path(__file__).resolve().parent.parent
BASE_DIR = BACKEND_DIR / "data" / "projects"
SPEC_PATH = BACKEND_DIR / "api_spec.json"

PROJECT_ALIASES: Dict[str, str] = {
    "vinyl_angel": "music_app",
    "universe-25": "universe_25",
    "golden_hour": "universe_25",
    "golden-hour": "universe_25",
    "modern_day": "universe_25",
    "modern-day": "universe_25",
}

def resolve_project_id(project_id: str) -> str:
    direct_path = BASE_DIR / project_id / "index.json"
    if direct_path.exists():
        return project_id
    if project_id in PROJECT_ALIASES:
        aliased_id = PROJECT_ALIASES[project_id]
        if (BASE_DIR / aliased_id / "index.json").exists():
            return aliased_id
    return project_id

def load_global_spec() -> Dict[str, Any]:
    if not SPEC_PATH.exists():
        raise HTTPException(status_code=500, detail=f"Missing configuration file api_spec.json at: {SPEC_PATH}")
    with open(SPEC_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

def load_project_index(project_id: str) -> Dict[str, Any]:
    resolved_id = resolve_project_id(project_id)
    index_path = BASE_DIR / resolved_id / "index.json"
    if not index_path.exists():
        raise HTTPException(status_code=404, detail=f"Project '{project_id}' not found at: {index_path}")
    with open(index_path, "r", encoding="utf-8") as f:
        return json.load(f)

def write_error_log(project_id: str, message: str):
    try:
        resolved_id = resolve_project_id(project_id)
        log_dir = BASE_DIR / resolved_id / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        with open(log_dir / "error.log", "a", encoding="utf-8") as f:
            f.write(f"[{datetime.now().isoformat()}] {message}\n")
    except Exception:
        pass

def infer_sqlite_column_type(val: Any) -> str:
    if isinstance(val, bool):
        return "INTEGER"
    if isinstance(val, int):
        return "INTEGER"
    if isinstance(val, float):
        return "REAL"
    return "TEXT"

def _parse_exclude_list(exclude_val: Any) -> List[str]:
    if not exclude_val:
        return []
    if isinstance(exclude_val, (list, set, tuple)):
        return [str(c).strip() for c in exclude_val if str(c).strip() and str(c).strip() not in ["NONE", "ALL"]]
    if isinstance(exclude_val, str):
        val = exclude_val.strip()
        if not val or val in ["NONE", "ALL"]:
            return []
        if (val.startswith("[") and val.endswith("]")) or (val.startswith("(") and val.endswith(")")):
            try:
                parsed = json.loads(val)
                if isinstance(parsed, list):
                    return [str(c).strip() for c in parsed if str(c).strip() and str(c).strip() not in ["NONE", "ALL"]]
            except Exception:
                pass
        if "," in val:
            parts = [p.strip() for p in val.split(",") if p.strip() and p.strip() not in ["NONE", "ALL"]]
            if parts:
                return parts
        return [val]
    return []

def _build_hazard_filter_clause(conn: sqlite3.Connection, app_data_dir: Path, hazard_cap: Any) -> Optional[str]:
    """
    Constructs an ultra-fast SQLite filter clause against _4_display.db (t4_db).
    _4_display.db is the single source of truth for hazard levels.
    All track IDs not present in _4_display.db are unrated tracks (baseline 3.0).
    """
    if hazard_cap is None:
        return None
    h_str = str(hazard_cap).strip().lower()
    if h_str in ["none", "all", "inf", "", "all tracks"]:
        return None

